#include "elevsim.h"
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <inttypes.h>

typedef struct { char **v; size_t n, cap; } Paths;
static void paths_free(Paths *p){if(!p)return;for(size_t i=0;i<p->n;i++)free(p->v[i]);free(p->v);memset(p,0,sizeof *p);}
static bool paths_add(Paths*p,const char*a,const char*b,EsError*e){size_t na=strlen(a),nb=strlen(b);if(na>SIZE_MAX-nb-1){es_error(e,8,0,"output path too long");return false;}if(p->n==p->cap){size_t nc=p->cap?p->cap*2:16;char**nv=es_realloc(p->v,nc*sizeof*nv,e);if(!nv)return false;p->v=nv;p->cap=nc;}char*s=es_malloc(na+nb+1,e);if(!s)return false;memcpy(s,a,na);memcpy(s+na,b,nb+1);p->v[p->n++]=s;return true;}
static bool add_run_targets(Paths*p,const Config*c,const char*pfx,bool include_trace,EsError*e){if(!paths_add(p,pfx,".manifest.json",e))return false;if(c->out_summary_json&&!paths_add(p,pfx,".summary.json",e))return false;if(c->out_summary_txt&&!paths_add(p,pfx,".summary.txt",e))return false;if(c->out_passenger&&!paths_add(p,pfx,".passengers.csv",e))return false;if(c->out_elevator&&!paths_add(p,pfx,".elevator_samples.csv",e))return false;if(c->out_event&&!paths_add(p,pfx,".events.log",e))return false;if(c->out_hist&&!paths_add(p,pfx,".wait_histogram.txt",e))return false;if(include_trace){if(!paths_add(p,pfx,".trace.csv",e)||!paths_add(p,pfx,".trace_info.json",e))return false;}return true;}
static char*join3(const char*a,const char*b,const char*c,EsError*e){size_t n=strlen(a)+strlen(b)+strlen(c);char*s=es_malloc(n+1,e);if(!s)return NULL;strcpy(s,a);strcat(s,b);strcat(s,c);return s;}
static void usage(FILE*f){fputs("Usage:\n  elevsim validate <scenario>\n  elevsim generate <scenario> --out <trace.csv> [--force]\n  elevsim run <scenario> --algorithm <algorithm-id> --out <output-prefix> [--force]\n  elevsim compare <scenario> --out <output-prefix> [--force]\n  elevsim replay <scenario> --trace <trace.csv> --algorithm <algorithm-id> --out <output-prefix> [--force]\n  elevsim --help\n  elevsim --version\n",f);}
static void command_help(const char*c){if(!strcmp(c,"validate"))puts("Usage: elevsim validate <scenario>");else if(!strcmp(c,"generate"))puts("Usage: elevsim generate <scenario> --out <trace.csv> [--force]");else if(!strcmp(c,"run"))puts("Usage: elevsim run <scenario> --algorithm <algorithm-id> --out <output-prefix> [--force]");else if(!strcmp(c,"compare"))puts("Usage: elevsim compare <scenario> --out <output-prefix> [--force]");else if(!strcmp(c,"replay"))puts("Usage: elevsim replay <scenario> --trace <trace.csv> --algorithm <algorithm-id> --out <output-prefix> [--force]");else usage(stdout);}
typedef struct{const char*out,*trace,*alg;bool force;} Opt;
static bool parse_opts(int argc,char**argv,int start,bool want_out,bool want_trace,bool want_alg,Opt*o,EsError*e){memset(o,0,sizeof*o);for(int i=start;i<argc;i++){const char*x=argv[i];if(!strcmp(x,"--force")){if(o->force){es_error(e,2,0,"duplicate --force");return false;}o->force=true;}else if(!strcmp(x,"--out")||!strcmp(x,"--trace")||!strcmp(x,"--algorithm")){const char**dst=!strcmp(x,"--out")?&o->out:!strcmp(x,"--trace")?&o->trace:&o->alg;if(*dst){es_error(e,2,0,"duplicate option %s",x);return false;}if(i+1>=argc){es_error(e,2,0,"missing value for %s",x);return false;}*dst=argv[++i];}else{es_error(e,2,0,"unknown option or extra argument: %s",x);return false;}}
if((want_out&&(!o->out||!*o->out))||(want_trace&&(!o->trace||!*o->trace))||(want_alg&&(!o->alg||!*o->alg))){es_error(e,2,0,"missing required option");return false;}if(!want_out&&o->out){es_error(e,2,0,"--out not allowed");return false;}if(!want_trace&&o->trace){es_error(e,2,0,"--trace not allowed");return false;}if(!want_alg&&o->alg){es_error(e,2,0,"--algorithm not allowed");return false;}if(!want_out&&!want_trace&&!want_alg&&o->force){es_error(e,2,0,"--force not allowed");return false;}return true;}
static bool prepare_trace(const Config*c,const char*override,Trace*t,EsError*e){trace_init(t);return override?trace_import(override,c,t,e):(c->traffic_generated?trace_generate(c,t,e):trace_import(c->trace_file,c,t,e));}
static void diag(const EsError*e){fprintf(stderr,"elevsim: %s%s%d%s\n",e->msg[0]?e->msg:"operation failed",e->line?" (line ":"",e->line,e->line?")":"");}
static bool failed_compare_text(const char*pfx,const char*alg,const EsError*why){size_t n=strlen(pfx)+16;char*p=malloc(n);if(!p)return false;snprintf(p,n,"%s.comparison.txt",pfx);FILE*f=fopen(p,"wb");free(p);if(!f)return false;fprintf(f,"STATUS: FAILED\nFailed algorithm: %s\nReason: %s\n",alg,why->msg);return fclose(f)==0;}
int main(int argc,char**argv){EsError e={0};Config c;Trace t;Paths paths={0};Metrics *ms=NULL;int rc=0;if(argc==2&&!strcmp(argv[1],"--help")){usage(stdout);return 0;}if(argc==2&&!strcmp(argv[1],"--version")){puts(ES_VERSION);return 0;}if(argc<2){usage(stderr);return 2;}const char*cmd=argv[1];if(argc==3&&!strcmp(argv[2],"--help")){command_help(cmd);return (!strcmp(cmd,"validate")||!strcmp(cmd,"generate")||!strcmp(cmd,"run")||!strcmp(cmd,"compare")||!strcmp(cmd,"replay"))?0:2;}if(strcmp(cmd,"validate")&&strcmp(cmd,"generate")&&strcmp(cmd,"run")&&strcmp(cmd,"compare")&&strcmp(cmd,"replay")){es_error(&e,2,0,"unknown command: %s",cmd);diag(&e);return 2;}if(argc<3){es_error(&e,2,0,"missing scenario");diag(&e);return 2;}const char*scenario=argv[2];Opt o;
if(!strcmp(cmd,"validate")){if(argc!=3){es_error(&e,2,0,"validate takes only a scenario");diag(&e);return 2;}if(!config_load(scenario,&c,&e)){diag(&e);return e.code?e.code:8;}if(!c.traffic_generated){trace_init(&t);if(!trace_import(c.trace_file,&c,&t,&e)){config_free(&c);diag(&e);return e.code?e.code:5;}trace_free(&t);}printf("OK validate %s\n",scenario);config_free(&c);return 0;}
if(!parse_opts(argc,argv,3,strcmp(cmd,"validate")!=0&&!strcmp(cmd,"generate")?true:(!strcmp(cmd,"run")||!strcmp(cmd,"compare")||!strcmp(cmd,"replay")),!strcmp(cmd,"replay"),!strcmp(cmd,"run")||!strcmp(cmd,"replay"),&o,&e)){diag(&e);return 2;}
if(!config_load(scenario,&c,&e)){diag(&e);return e.code?e.code:8;}
if(o.alg&&alg_index(o.alg)<0){es_error(&e,4,0,"unknown algorithm id: %s",o.alg);goto fail;}
if(!strcmp(cmd,"generate")){if(!c.traffic_generated){es_error(&e,4,0,"generate requires traffic.mode=generated");goto fail;}if(!paths_add(&paths,o.out,"",&e)||!paths_add(&paths,o.out,".info.json",&e))goto fail;if(!reserve_targets(paths.v,paths.n,o.force,&e))goto fail;if(!trace_generate(&c,&t,&e))goto fail_reserved;if(!trace_write(&t,o.out,&e))goto fail_trace_reserved;char*ip=join3(o.out,".info", ".json",&e);if(!ip)goto fail_trace_reserved;if(!trace_info_write(&t,&c,ip,"generated",&e)){free(ip);goto fail_trace_reserved;}free(ip);trace_free(&t);printf("OK generate %s\n",o.out);goto success;}
if(!strcmp(cmd,"run")||!strcmp(cmd,"replay")){int ai=alg_index(o.alg);if(!add_run_targets(&paths,&c,o.out,true,&e))goto fail;if(!reserve_targets(paths.v,paths.n,o.force,&e))goto fail;if(!prepare_trace(&c,!strcmp(cmd,"replay")?o.trace:NULL,&t,&e))goto fail_reserved;Metrics m={0};if(!simulate(&c,&t,ai,o.out,!strcmp(cmd,"replay")?"replay":"run",&m,&e,o.force,false)){metrics_free(&m);goto fail_trace_reserved;}metrics_free(&m);trace_free(&t);printf("OK %s %s\n",cmd,o.out);goto success;}
if(!strcmp(cmd,"compare")){if(!paths_add(&paths,o.out,".trace.csv",&e)||!paths_add(&paths,o.out,".trace_info.json",&e)||!paths_add(&paths,o.out,".comparison.txt",&e))goto fail;if(c.out_comparison_csv&&!paths_add(&paths,o.out,".comparison.csv",&e))goto fail;for(size_t i=0;i<c.compare_n;i++){char*pfx=join3(o.out,".",c.compare[i],&e);if(!pfx)goto fail;bool ok=add_run_targets(&paths,&c,pfx,false,&e);free(pfx);if(!ok)goto fail;}if(!reserve_targets(paths.v,paths.n,o.force,&e))goto fail;if(!prepare_trace(&c,NULL,&t,&e))goto fail_reserved;char*tp=join3(o.out,".trace",".csv",&e),*ti=join3(o.out,".trace_info",".json",&e);if(!tp||!ti){free(tp);free(ti);goto fail_trace_reserved;}if(!trace_write(&t,tp,&e)||!trace_info_write(&t,&c,ti,c.traffic_generated?"generated":"trace",&e)){free(tp);free(ti);goto fail_trace_reserved;}free(tp);free(ti);ms=es_calloc(c.compare_n,sizeof*ms,&e);if(!ms)goto fail_trace_reserved;for(size_t i=0;i<c.compare_n;i++){int ai=alg_index(c.compare[i]);char*pfx=join3(o.out,".",c.compare[i],&e);if(!pfx)goto fail_compare;if(!simulate(&c,&t,ai,pfx,"compare_child",&ms[i],&e,o.force,true)){free(pfx);failed_compare_text(o.out,c.compare[i],&e);goto fail_compare;}free(pfx);}if(!write_comparison(&c,&t,o.out,ms,c.compare_n,&e))goto fail_compare;for(size_t i=0;i<c.compare_n;i++)metrics_free(&ms[i]);free(ms);ms=NULL;trace_free(&t);printf("OK compare %s\n",o.out);goto success;}
es_error(&e,2,0,"unreachable command");
fail_compare:if(ms){for(size_t i=0;i<c.compare_n;i++)metrics_free(&ms[i]);free(ms);ms=NULL;}trace_free(&t);goto fail_reserved_no_cleanup;
fail_trace_reserved:trace_free(&t);
fail_reserved:if(!o.force)cleanup_targets(paths.v,paths.n);
fail_reserved_no_cleanup:rc=e.code?e.code:8;diag(&e);config_free(&c);paths_free(&paths);return rc;
fail:rc=e.code?e.code:8;diag(&e);config_free(&c);paths_free(&paths);return rc;
success:config_free(&c);paths_free(&paths);return 0;}
